        native(seed[0]),
        native(seed[1]),
        native(seed[2]),
        native(seed[3]),
    );
    let (mut a10, mut a11, mut a12, mut a13) = (
        native(seed[0]),
        native(seed[1]),
        native(seed[2]),
        native(seed[3]),
    );
    let (mut a20, mut a21, mut a22, mut a23) = (
        native(seed[0]),
        native(seed[1]),
        native(seed[2]),
        native(seed[3]),
    );
    let (mut a30, mut a31, mut a32, mut a33) = (
        native(seed[0]),
        native(seed[1]),
        native(seed[2]),
        native(seed[3]),
