        }
        {
            // SAFETY: the K tail remains in this checked row.
            let value = unsafe { *rows[3].get_unchecked(k) };
            a30 = vfmaq_n_f32(a30, w0, value);
            a31 = vfmaq_n_f32(a31, w1, value);
            a32 = vfmaq_n_f32(a32, w2, value);
